int mlx4_register_mac(struct mlx4_dev *dev, u8 port, u64 mac, int *index)
{
	int i;
	int err = -ENOSPC;

	mutex_lock(&dev->mac_table.mutex);

	/* Check if MAC is already registered */
	for (i = 0; i < MLX4_MAX_MAC_ADDRS; i++) {
		if (dev->mac_table.macs[i].port == port &&
		    dev->mac_table.macs[i].mac == mac) {
			dev->mac_table.macs[i].ref_count++;
			*index = i;
			mutex_unlock(&dev->mac_table.mutex);
			return 0;
		}
	}

	/* Find a free entry */
	for (i = 0; i < MLX4_MAX_MAC_ADDRS; i++) {
		if (dev->mac_table.macs[i].ref_count == 0) {
			dev->mac_table.macs[i].port = port;
			dev->mac_table.macs[i].mac = mac;
			dev->mac_table.macs[i].ref_count = 1;
			*index = i;

			/* Update hardware with the new MAC */
			err = mlx4_SET_PORT_ETH_ADDR(dev, port, mac);
			if (err)
				goto out;

			mutex_unlock(&dev->mac_table.mutex);
			return 0;
		}
	}

out:
	mutex_unlock(&dev->mac_table.mutex);
	return err;
}

int mlx4_register_mac(struct mlx4_dev *dev, u8 port, u64 mac, int *index)
{
	int i;
	int err = 0;

	mutex_lock(&dev->mac_table.mutex);

	/* Check if MAC already exists in the table */
	for (i = 0; i < dev->mac_table.size; ++i) {
		if (dev->mac_table.entry[i].ref_count &&
		    dev->mac_table.entry[i].port == port &&
		    dev->mac_table.entry[i].mac == mac) {
			/* MAC already registered, increment ref count */
			dev->mac_table.entry[i].ref_count++;
			*index = i;
			goto out;
		}
	}

	/* Find a free entry in the MAC table */
	for (i = 0; i < dev->mac_table.size; ++i) {
		if (!dev->mac_table.entry[i].ref_count) {
			/* Register new MAC address */
			dev->mac_table.entry[i].mac = mac;
			dev->mac_table.entry[i].port = port;
			dev->mac_table.entry[i].ref_count = 1;

			/* Update hardware or firmware with new MAC */
			err = mlx4_WRITE_MAC(dev, port, mac);
			if (err) {
				mlx4_dbg(dev, "Failed to write MAC address to hardware\n");
				goto out;
			}

			*index = i;
			goto out;
		}
	}

	/* No available entries */
	err = -ENOSPC;
	mlx4_dbg(dev, "MAC table is full\n");

out:
	mutex_unlock(&dev->mac_table.mutex);
	return err;
}

int mlx4_register_mac(struct mlx4_dev *dev, u8 port, u64 mac, int *index)
{
        int err = 0;
        int i;
        struct mlx4_mac_table *table = &dev->mac_table[port - 1];

        mutex_lock(&table->mutex);

        for (i = 0; i < MLX4_MAC_TABLE_SIZE; ++i) {
                if (table->macs[i].mac == mac) {
                        table->macs[i].ref_count++;
                        *index = i;
                        mutex_unlock(&table->mutex);
                        return 0;
                }
        }

        for (i = 0; i < MLX4_MAC_TABLE_SIZE; ++i) {
                if (!table->macs[i].ref_count) {
                        table->macs[i].mac = mac;
                        table->macs[i].ref_count = 1;
                        *index = i;
                        break;
                }
        }

        if (i == MLX4_MAC_TABLE_SIZE) {
                mutex_unlock(&table->mutex);
                return -ENOSPC;
        }

        err = mlx4_WRITE_MAC_table(dev, port, *index, mac);
        if (err < 0) {
                table->macs[i].mac = 0;
                table->macs[i].ref_count = 0;
                mutex_unlock(&table->mutex);
                return err;
        }

        mutex_unlock(&table->mutex);
        return 0;
}

